-- Generated by npm run db:seed from public/data.js. Review and commit together.
-- Public, editor-added records. No representatives, contacts, votes or verified
-- ownership are invented. Existing profiles and signals are never overwritten.
insert into public.sources (
  slug,name,website_url,canonical_domain,publisher,about,logo_path,country_code,coverage,
  kinds,content_types,methods,topics,research_languages,access_type,checked_at,
  provenance,status,published_at
)
values
('college-toolkit','Crime Reduction Toolkit','https://www.college.police.uk/research/crime-reduction-toolkit','college.police.uk','College of Policing','The College of Policing’s toolkit summarises research on crime reduction interventions. It links to systematic reviews and sets out findings on effects, how approaches may work, relevant settings, implementation and costs. It supports comparison of approaches rather than replacing assessment of the underlying studies and local conditions.',null,'GB',array['GB','global']::text[],array['Official','Research collection']::text[],array['Evidence reviews','Research summaries']::text[],array['Systematic reviews']::text[],array['Crime prevention','Neighbourhood policing','Violence prevention']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('global-policing-database','Global Policing Database','https://gpd.uq.edu.au/','gpd.uq.edu.au','University of Queensland / University of South Carolina','A searchable international collection of evaluations of police and policing interventions, developed through university collaboration. Subscribers can search coded study information and follow references to papers, reports and theses. Introductory information is public; access to the database and to individual full texts follows separate subscription and publication arrangements.','/assets/sources/global-policing-database-logo.svg','AU',array['global','AU','GB','US']::text[],array['University','Academic','Research collection']::text[],array['Original research','Evidence reviews']::text[],array['Randomised controlled trials','Quasi-experimental','Systematic reviews']::text[],array['Crime prevention','Investigations','Police wellbeing','Leadership']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cebcp-matrix','Evidence-Based Policing Matrix','https://cebcp.org/evidence-based-policing/the-matrix/','cebcp.org','Center for Evidence-Based Crime Policy, George Mason University','A research translation tool collecting evaluations of police interventions intended to reduce crime and disorder. Studies are grouped by their targets, focus and proactivity, with accessible descriptions and links to the research. The publisher currently reports coverage through 2022, with an update through 2025 underway.','/assets/sources/cebcp-matrix-logo.png','US',array['global','US','GB']::text[],array['University','Academic','Research collection']::text[],array['Original research','Research summaries']::text[],array['Randomised controlled trials','Quasi-experimental']::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('sebp','Society of Evidence Based Policing','https://www.sebp.police.uk/','sebp.police.uk','Society of Evidence Based Policing','An independent UK society connecting policing practitioners and researchers through research briefings, events, learning materials and professional networks. Its website provides public resources alongside membership information and links to regional coordinators. The society promotes the use of evidence in policing and collaboration with related international societies.','/assets/sources/sebp-logo.jpg','GB',array['GB','global']::text[],array['EBP society','Professional society','Charity']::text[],array['Learning resources','Research summaries','Practice examples']::text[],array[]::text[],array['Neighbourhood policing','Leadership','Crime prevention']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('college-practice','Practice Bank','https://www.college.police.uk/support-forces/practices','college.police.uk','College of Policing','The College of Policing’s Practice Bank shares accounts of policing and community safety interventions submitted by participating organisations. Entries describe local problems, practical responses, implementation and learning, with evaluation information where available. The strength of evaluation varies between entries, so inclusion does not establish that an approach is effective.',null,'GB',array['GB']::text[],array['Official','Practice collection']::text[],array['Practice examples','Implementation guides']::text[],array[]::text[],array['Neighbourhood policing','Crime prevention','Leadership']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('yef','Youth Endowment Fund Toolkit','https://youthendowmentfund.org.uk/toolkit/','youthendowmentfund.org.uk','Youth Endowment Fund','A toolkit bringing together research on approaches to preventing violence involving children and young people. Entries explain the available evidence, estimated effects, costs and practical delivery considerations across policing, education and other services. Users can follow links to the underlying reviews and guidance when considering local implementation.','/assets/sources/yef-logo.svg','GB',array['GB','global']::text[],array['Charity','Research collection']::text[],array['Evidence reviews','Implementation guides']::text[],array['Systematic reviews']::text[],array['Violence prevention','Safeguarding','Crime prevention']::text[],array['en','cy']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('pop-centre','Center for Problem-Oriented Policing','https://popcenter.asu.edu/','popcenter.asu.edu','Arizona State University','An Arizona State University resource centre for problem-oriented policing. Its guides, analytical tools and project examples help practitioners understand recurring crime and disorder problems, develop responses and assess results. The collection includes international case studies and selected translated publications; individual projects differ in the strength of their evaluation.','/assets/sources/pop-centre-logo.png','US',array['global','US','GB']::text[],array['University','Academic','Practice collection']::text[],array['Implementation guides','Practice examples','Learning resources']::text[],array[]::text[],array['Neighbourhood policing','Crime prevention']::text[],array['en','id','ms','bs','zh','cs','nl','et','fa','fr','de','he','it','ja','ko','lo','lv','mn','pt','ru','sl','es','sv','th','tr','vi']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('can-sebp','Canadian Society of Evidence-Based Policing','https://www.can-sebp.net/','can-sebp.net','Canadian Society of Evidence-Based Policing','A Canadian practitioner and researcher society promoting the use of research in policing. Its resource hub includes introductory materials, evidence briefs and signposts for frontline practice, alongside events and professional networking. Public material is available on the website, while some society activities and resources may have membership requirements.','/assets/sources/can-sebp-logo.png','CA',array['CA','global']::text[],array['EBP society','Professional society']::text[],array['Research summaries','Learning resources']::text[],array[]::text[],array['Leadership','Crime prevention','Neighbourhood policing','Police wellbeing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cepol','CEPOL — Scientific knowledge and research','https://www.cepol.europa.eu/scientific-knowledge-and-research/scientific-resources-and-projects','cepol.europa.eu','European Union Agency for Law Enforcement Training','The European Union Agency for Law Enforcement Training provides scientific resources, research publications and links connecting law enforcement training with research. Material includes the European Law Enforcement Research Bulletin, conferences and related projects. Public publications can be explored online; participation in particular training activities may have separate eligibility requirements.','/assets/sources/cepol-identity.svg','HU',array['region:Europe','global']::text[],array['Official','Learning provider']::text[],array['Learning resources','Original research','Research summaries']::text[],array[]::text[],array['Investigations','Leadership','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('iacp','IACP Evidence to Action Directory','https://www.theiacp.org/iacp-evidence-to-action-directory','theiacp.org','International Association of Chiefs of Police','The International Association of Chiefs of Police’s Evidence to Action Directory offers short research briefs for policing leaders and practitioners. The collection translates findings into accessible summaries covering operational decisions, community relationships, organisational practice and officer wellbeing. Readers can use the referenced studies to assess findings and their relevance locally.','/assets/sources/iacp-logo.svg','US',array['US','global']::text[],array['Professional society']::text[],array['Research summaries']::text[],array[]::text[],array['Leadership','Police wellbeing','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('ebp-app','Evidence-Based Policing App — Resources','https://www.evidence-basedpolicing.org/evidence-based-policing-resources/','evidence-basedpolicing.org','Police Foundation, with CEBCP and IACP','A public resource page accompanying the Evidence-Based Policing App, linking to research summaries, learning modules and practical strategies. It signposts collections including the Policing Matrix and systematic reviews. The publisher explicitly notes that some suggested responses have not been evaluated and should not be treated as established evidence.','/assets/sources/ebp-app-logo.jpg','US',array['global','US','GB']::text[],array['Research collection']::text[],array['Learning resources','Research summaries','Practice examples']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('tap','Thinking About Policing','https://thinkingaboutpolicing.org/','thinkingaboutpolicing.org','Nathan Tracey','An independent website by Nathan Tracey connecting British policing research, policy, leadership and operational experience. Articles explain practical questions and link to original sources, alongside research tools and learning resources. The writing reflects the author’s personal capacity; it is research interpretation and commentary rather than a university research programme.','/assets/sources/tap-logo.png','GB',array['GB']::text[],array['Independent','Blog']::text[],array['Commentary','Research summaries','Practice examples']::text[],array[]::text[],array['Leadership','Technology','Neighbourhood policing','Safeguarding']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('police-science-dr','Police Science Dr','https://www.policesciencedr.com/','policesciencedr.com','Raven’s Ocean Ltd / Dr Susanne Knabe-Nicol','A research communication platform created by Dr Susanne Knabe-Nicol to make policing research accessible to practitioners. It publishes short research briefings, videos, podcasts and related learning materials covering investigations, psychology and evidence-based practice. Some transcripts require joining the free mailing list, and separate courses may require payment.','/assets/sources/police-science-dr-logo.jpg','GB',array['global','GB']::text[],array['Company','Learning provider','Blog']::text[],array['Research summaries','Learning resources']::text[],array[]::text[],array['Investigations','Leadership','Crime prevention','Police wellbeing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cambridge-ebp','Cambridge Centre for Evidence-Based Policing','https://www.cambridge-ebp.co.uk/','cambridge-ebp.co.uk','Cambridge Centre for Evidence-Based Policing Ltd','An independent research, consultancy and professional training organisation working with police services internationally. Its website provides information on evidence-based policing courses, evaluation work, problem-solving and crime harm measurement, with selected research resources. It is a separate organisation from the University of Cambridge; access conditions vary between publications, courses and services.','/assets/sources/cambridge-ebp-logo.png','GB',array['global','GB']::text[],array['Company','Learning provider']::text[],array['Original research','Learning resources','Practice examples']::text[],array['Randomised controlled trials','Quasi-experimental']::text[],array['Crime prevention','Investigations','Leadership','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('nij-crimesolutions','CrimeSolutions','https://crimesolutions.ojp.gov/','crimesolutions.ojp.gov','National Institute of Justice','A National Institute of Justice collection of programme profiles, practice reviews and evidence ratings covering policing and wider criminal justice interventions. It explains the review process and links findings to evaluations and meta-analyses. The publisher states that the website is no longer updated, so information and links may be outdated.','/assets/sources/nij-crimesolutions-logo.svg','US',array['global','US']::text[],array['Official','Research collection']::text[],array['Evidence reviews','Research summaries']::text[],array['Randomised controlled trials','Quasi-experimental','Systematic reviews']::text[],array['Crime prevention','Neighbourhood policing','Violence prevention','Safeguarding']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('campbell','Campbell Crime and Justice','https://www.campbellcollaboration.org/crime/','campbellcollaboration.org','Campbell Collaboration','An international research network coordinating systematic reviews of interventions to prevent crime and improve justice. The Crime and Justice group links to published reviews, research teams and guidance for contributors, covering policing and other parts of the justice system. Review methods and coverage dates should be checked for each publication.','/assets/sources/campbell-logo.svg','US',array['global']::text[],array['Charity','Research collection']::text[],array['Evidence reviews','Research summaries']::text[],array['Systematic reviews']::text[],array['Crime prevention','Investigations','Violence prevention','Safeguarding']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('anzsebp','Australia & New Zealand Society of Evidence Based Policing','https://www.anzsebp.com/','anzsebp.com','Australia & New Zealand Society of Evidence Based Policing','A society promoting collaboration between policing practitioners and researchers in Australia and New Zealand. Its website shares research resources, professional events and editions of Police Science, with public and member material. The visible journal archive includes editions through 2024; readers should check individual publication dates when seeking recent research.','/assets/sources/anzsebp-logo.png','AU',array['AU','NZ','global']::text[],array['EBP society','Professional society']::text[],array['Research summaries','Learning resources','Practice examples']::text[],array[]::text[],array['Crime prevention','Leadership','Investigations']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('asebp','American Society of Evidence-Based Policing','https://americansebp.org/','americansebp.org','American Society of Evidence-Based Policing','A professional society connecting policing practitioners and researchers through learning opportunities, conferences and research briefs. Publicly available briefs cover topics such as crime prevention, technology, leadership and officer wellbeing. The complete research brief collection is offered through membership, and the publicly displayed selection may rotate over time.','/assets/sources/asebp-logo.webp','US',array['US','global']::text[],array['EBP society','Professional society']::text[],array['Research summaries','Learning resources']::text[],array[]::text[],array['Crime prevention','Leadership','Technology','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('sebp-nl','Society of Evidence-based Policing Nederland','https://sebp.nl/','sebp.nl','Society of Evidence-based Policing Nederland','A Dutch society encouraging practitioners and researchers to use evidence in everyday policing. Its website shares research signposts, knowledge summaries, learning materials, recorded discussions and events. Most listed material is in Dutch, with links to research and related networks; inclusion of a resource does not replace appraisal of its underlying evidence.','/assets/sources/sebp-nl-logo.png','NL',array['NL','global']::text[],array['EBP society','Professional society']::text[],array['Research summaries','Learning resources','Commentary']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing','Leadership']::text[],array['nl']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('nz-ebpc','New Zealand Evidence-Based Policing Centre','https://www.police.govt.nz/about-us/programmes-and-initiatives/evidence-based-policing','police.govt.nz','New Zealand Police','New Zealand Police’s Evidence-Based Policing Centre connects research, evaluation and operational practice. Public pages describe the centre, its partnerships, projects and research outputs, and provide information for researchers interested in working with police. Publications and evaluation reports should be read in the context of their New Zealand setting and study dates.','/assets/sources/nz-ebpc-logo.png','NZ',array['NZ','global']::text[],array['Official','Research collection']::text[],array['Original research','Evidence reviews','Research summaries']::text[],array[]::text[],array['Crime prevention','Investigations','Leadership','Safeguarding']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('sipr','Scottish Institute for Policing Research','https://sipr.ac.uk/publications/','sipr.ac.uk','Scottish Institute for Policing Research','The Scottish Institute for Policing Research connects universities and policing partners to support independent multidisciplinary research. Its public collection includes research reports, briefing papers, practitioner fellowship outputs, webinars and annual reports. Topics cover policing organisations, communities, investigation and emerging challenges, with a particular focus on research relevant to Scotland.',null,'GB',array['region:Scotland']::text[],array['Academic']::text[],array['Original research']::text[],array[]::text[],array['Leadership','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('ucl-jdi','UCL Jill Dando Institute of Security and Crime Science','https://www.ucl.ac.uk/engineering/jill-dando-institute','ucl.ac.uk','UCL Jill Dando Institute of Security and Crime Science','UCL’s Jill Dando Institute brings together multidisciplinary research on reducing crime and improving security. Its website links to research groups, publications, news, events and professional development opportunities. Teaching is delivered through UCL Security and Crime Science, while the institute connects expertise from several university departments and external partners.','/assets/sources/ucl-jdi-identity.svg','GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Crime prevention','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('ou-cprl','Open University Centre for Policing Research and Learning','https://university.open.ac.uk/centres/policing/','university.open.ac.uk','Open University Centre for Policing Research and Learning','The Open University’s Centre for Policing Research and Learning develops research and professional learning with policing partners. Work spans policing challenges, organisational practice, innovation and emerging technology. Public pages describe projects, partnerships and events; some reports and collaborative resources are available through a separate members area for participating organisations.','/assets/sources/ou-cprl-identity.svg','GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Leadership','Police wellbeing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cardiff-upsi','Universities’ Police Science Institute','https://www.cardiff.ac.uk/security-crime-intelligence-innovation-institute/research/groups/universities-police-science-institute','cardiff.ac.uk','Universities’ Police Science Institute','Cardiff University’s Universities’ Police Science Institute develops research with police and partner organisations to inform policing policy and practice. Its work covers vulnerability and high-harm crime, neighbourhood partnerships, digital policing and counter-terrorism. The site includes project highlights and examples of research supporting police learning and decision-making.',null,'GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Neighbourhood policing','Safeguarding']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('portsmouth-policing','University of Portsmouth Policing Research Group','https://www.port.ac.uk/research/research-groups-and-centres/policing-research-group','port.ac.uk','University of Portsmouth Policing Research Group','The University of Portsmouth’s Policing Research Group brings together researchers, postgraduate students and former practitioners studying police organisations and their relationships with the public. Its themes include culture, diversity, trust, wellbeing and organisational justice. The page links to publications, public research blogs, staff profiles and examples of work with police partners.','/assets/sources/portsmouth-policing-identity.webp','GB',array['GB']::text[],array['University','Academic','Blog']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Investigations','Leadership','Police wellbeing','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('ljmu-policing','Liverpool Centre for Advanced Policing Studies','https://www.ljmu.ac.uk/research/centres-and-institutes/lcaps-research','ljmu.ac.uk','Liverpool Centre for Advanced Policing Studies','Liverpool John Moores University’s Centre for Advanced Policing Studies conducts research across policing, criminal justice, criminology, law and psychology. Its research clusters cover investigation and intelligence, safeguarding and vulnerability, police organisations and education, and serious organised crime and terrorism. The page introduces projects, research expertise and routes to staff profiles.','/assets/sources/ljmu-policing-identity.webp','GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Investigations','Leadership']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cambridge-criminology','University of Cambridge Institute of Criminology','https://www.crim.cam.ac.uk/','crim.cam.ac.uk','University of Cambridge Institute of Criminology','The University of Cambridge’s Institute of Criminology conducts research and postgraduate teaching across criminology, criminal justice and policing. Its website provides routes to research centres, projects, publications and the Cambridge Crime Harm Index. It also introduces courses, researchers, library resources and events, including applied criminology and police management programmes.','/assets/sources/cambridge-criminology-identity.svg','GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Crime prevention','Leadership']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('vulnerability-futures','Vulnerability & Policing Futures Research Centre','https://vulnerabilitypolicing.org.uk/research/','vulnerabilitypolicing.org.uk','Vulnerability & Policing Futures Research Centre','The Vulnerability & Policing Futures Research Centre examines how vulnerabilities are created, intensified and addressed through policing and other services. Co-hosted by the universities of Leeds and York, it studies issues including exploitation, domestic abuse, mental illness and homelessness. Its website provides research projects, publications, findings summaries and opportunities for collaboration.','/assets/sources/vulnerability-futures-identity.webp','GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Safeguarding','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('crest','Centre for Research and Evidence on Security Threats','https://crestresearch.ac.uk/resources/','crestresearch.ac.uk','Centre for Research and Evidence on Security Threats','The Centre for Research and Evidence on Security Threats shares behavioural and social science research relevant to security and policing. Its resource collection includes reports, practical guides, policy briefs and research summaries covering interviewing, risk assessment, radicalisation, disinformation and decision-making. Filters help readers locate material by topic, publication type and date.','/assets/sources/crest-identity.webp','GB',array['GB']::text[],array['Academic']::text[],array['Original research','Research summaries','Learning resources']::text[],array[]::text[],array['Investigations','Technology']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('police-foundation','The Police Foundation','https://www.police-foundation.org.uk/publications/','police-foundation.org.uk','The Police Foundation','The Police Foundation publishes independent research and analysis about policing and public safety. Its publications cover police reform, neighbourhood policing, public confidence, fraud, technology and organisational questions. The collection includes research reports, discussion papers and event outputs, with links to downloadable material and explanations of the issues each publication examines.','/assets/sources/police-foundation-identity.webp','GB',array['GB']::text[],array['Charity']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Leadership','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('justice-innovation','Centre for Justice Innovation','https://justiceinnovation.org/','justiceinnovation.org','Centre for Justice Innovation','The Centre for Justice Innovation works to improve how justice services respond to people and communities. Its website brings together research, practical resources and examples of service change, including diversion, procedural fairness and problem-solving approaches. Readers can explore its projects, publications and support for organisations developing and evaluating justice practice.','/assets/sources/justice-innovation-identity.svg','GB',array['GB']::text[],array['Charity']::text[],array['Research summaries','Implementation guides']::text[],array[]::text[],array['Safeguarding','Crime prevention']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('contextual-safeguarding','Contextual Safeguarding','https://www.contextualsafeguarding.org.uk/our-work/research/','contextualsafeguarding.org.uk','Durham University','Durham University’s Contextual Safeguarding programme researches how services can protect young people from harm beyond their families. The team works with young people, families and practitioners to inform policy and practice. Its website provides research projects, academic publications, toolkits and resources supporting responses to harm in peer, school and community settings.',null,'GB',array['GB']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Safeguarding','Violence prevention']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('childrens-society','The Children’s Society — county lines toolkit','https://www.childrenssociety.org.uk/information/professionals/resources/county-lines-toolkit','childrenssociety.org.uk','The Children’s Society — county lines toolkit','The Children’s Society’s county lines and criminal exploitation toolkit introduces exploitation affecting children and young people and offers practical suggestions for professionals supporting them. The public page links to a downloadable toolkit and related resources. Published in 2018, it should be read alongside newer safeguarding guidance and research when informing current practice.',null,'GB',array['GB']::text[],array['Charity']::text[],array['Implementation guides','Learning resources']::text[],array[]::text[],array['Safeguarding','Violence prevention']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('nspcc','NSPCC Learning','https://learning.nspcc.org.uk/','learning.nspcc.org.uk','NSPCC Learning','NSPCC Learning provides safeguarding and child protection research, statistics, guidance and professional resources. Readers can find research publications, case review material and support from its Library and Information Service, alongside training and consultancy. Its resources cover issues including abuse, neglect, online safety and how organisations can strengthen safeguarding practice.','/assets/sources/nspcc-identity.svg','GB',array['GB']::text[],array['Charity']::text[],array['Original research','Research summaries','Implementation guides']::text[],array[]::text[],array['Safeguarding']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('csa-centre','Centre of expertise on child sexual abuse','https://www.csacentre.org.uk/','csacentre.org.uk','Centre of expertise on child sexual abuse','The Centre of expertise on child sexual abuse brings together research, evidence and professional learning to improve prevention and responses to child sexual abuse. Hosted by Barnardo’s, it publishes research summaries, data analysis and practical resources for safeguarding professionals. The website also offers training, webinars and guidance for developing coordinated service responses.','/assets/sources/csa-centre-identity.webp','GB',array['GB']::text[],array['Charity']::text[],array['Original research','Research summaries','Implementation guides']::text[],array[]::text[],array['Safeguarding','Investigations']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('safelives','SafeLives — research and policy','https://safelives.org.uk/research-policy/','safelives.org.uk','SafeLives — research and policy','SafeLives publishes research, policy analysis and practitioner data to improve responses to domestic abuse. Its research and policy section provides routes to a research library, health-related resources and work concerning children, young people, men and boys. The material supports professionals and services seeking to understand experiences of abuse and improve support.','/assets/sources/safelives-identity.webp','GB',array['GB']::text[],array['Charity']::text[],array['Original research','Datasets','Implementation guides']::text[],array[]::text[],array['Safeguarding','Violence prevention']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('npcc-science','NPCC Science and Technology Library','https://science.police.uk/library/','science.police.uk','NPCC Science and Technology Library','The NPCC science and technology library provides publications and resources connected with policing science, innovation and research. Hosted by the Office of the Police Chief Scientific Adviser, the wider website connects policing with researchers and other partners. Readers can find reports, practical resources and links to scientific and technological work relevant to policing.','/assets/sources/npcc-science-identity.svg','GB',array['GB']::text[],array['Official']::text[],array['Original research','Practice examples','Implementation guides']::text[],array[]::text[],array['Technology','Investigations']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('foundations','Foundations — evidence and practice','https://foundations.org.uk/','foundations.org.uk','Foundations — evidence and practice','Foundations is the national What Works Centre for Children & Families. It generates and shares evidence to improve support for children and families, with work covering parenting, family networks, care-experienced children and domestic abuse. Its website offers publications, evaluation resources, practice guides and an evidence toolkit for policy and local service decisions.','/assets/sources/foundations-identity.svg','GB',array['GB']::text[],array['Charity']::text[],array['Evidence reviews','Implementation guides']::text[],array[]::text[],array['Safeguarding','Violence prevention']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('osce-policing','OSCE — community policing resources','https://tntd.osce.org/secretariat/107820','tntd.osce.org','OSCE — community policing resources','The OSCE’s community policing resource page introduces approaches based on police–public partnerships, public participation and shared problem-solving. It brings together guides, publications, related activities and learning opportunities from its Transnational Threats Department. The material supports discussion and development of community-oriented policing across the OSCE region, with an official unit contact provided.','/assets/sources/osce-policing-identity.svg','AT',array['region:Europe','region:Asia','region:North America']::text[],array['Official']::text[],array['Implementation guides','Learning resources','Practice examples']::text[],array[]::text[],array['Neighbourhood policing','Leadership']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('nscr','Netherlands Institute for the Study of Crime and Law Enforcement — police research','https://nscr.nl/en/theme/police-research/','nscr.nl','Netherlands Institute for the Study of Crime and Law Enforcement — police research','The Netherlands Institute for the Study of Crime and Law Enforcement’s police research programme examines how police actions work, in which circumstances and for whom. It works with police, universities and other knowledge institutions. The page introduces research themes, doctoral projects, researchers and routes to collaboration, including work on legitimacy and police practice.','/assets/sources/nscr-identity.svg','NL',array['NL','global']::text[],array['Academic']::text[],array['Original research']::text[],array[]::text[],array['Neighbourhood policing','Leadership']::text[],array['en','nl']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('dhpol','German Police University — research','https://www.dhpol.de/forschung/','dhpol.de','German Police University — research','The German Police University conducts research connecting policing, public administration and society. Its research priorities include leadership and organisation, operational management and communication, criminal investigation and law. The German-language website introduces research projects, funding support, doctoral study and contact routes, with an emphasis on transferring findings into police education and professional practice.','/assets/sources/dhpol-identity.webp','DE',array['DE','region:Europe']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Leadership','Technology']::text[],array['de']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('phs','Norwegian Police University College','https://www.politihogskolen.no/fag-og-forskning/','politihogskolen.no','Norwegian Police University College','Norway’s Police University College provides research and professional development connected with policing. Its research pages introduce projects, research groups and specialist staff, with routes to publications, research strategy and events. The website also describes international cooperation and digital policing work, including collaboration through the Nordic Computer Forensic Investigators network.','/assets/sources/phs-identity.webp','NO',array['NO']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Investigations','Leadership']::text[],array['no']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('polamk','Police University College Finland — research','https://polamk.fi/en/research-and-development','polamk.fi','Police University College Finland — research','Finland’s Police University College conducts applied research and development to support policing and internal security. Its research section introduces research, development and innovation activities, projects, student work and publishing. The site also explains research ethics and open science, and links findings with police education and the development of professional practice.',null,'FI',array['FI']::text[],array['University','Academic']::text[],array['Original research','Learning resources']::text[],array[]::text[],array['Leadership','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('bra','Swedish National Council for Crime Prevention','https://bra.se/english','bra.se','Swedish National Council for Crime Prevention','Brå, the Swedish National Council for Crime Prevention, is a government agency providing crime statistics, research and crime prevention knowledge. Its English-language website links to publications, official statistics and analyses of responses to crime. The collection includes studies relevant to policing and supports discussion of criminal justice policy and prevention practice.','/assets/sources/bra-identity.svg','SE',array['SE']::text[],array['Official']::text[],array['Original research','Datasets','Implementation guides']::text[],array[]::text[],array['Crime prevention','Violence prevention']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('malmo','Malmö Centre for Policing and Prevention','https://mau.se/en/research/malmo-centre-for-policing-and-prevention/','mau.se','Malmö Centre for Policing and Prevention','Malmö University’s Centre for Policing and Prevention researches evidence-informed approaches to crime prevention and policing. Its themes include preventing serious violence and youth recruitment, improving safety in local communities, and developing effective investigations using technology. The site provides research projects, publications and contacts, including work on focused deterrence and police–community collaboration.','/assets/sources/malmo-identity.svg','SE',array['SE']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Neighbourhood policing','Violence prevention']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('vive','VIVE — Danish Center for Social Science Research','https://www.vive.dk/en/','vive.dk','VIVE — Danish Center for Social Science Research','VIVE, the Danish Center for Social Science Research, is an independent research and analysis centre studying welfare and the public sector. Its English-language website introduces research areas, researchers and publications across children and families, social services, health and governance. It offers wider social evidence relevant to prevention and responses to vulnerability.','/assets/sources/vive-identity.webp','DK',array['DK','SE','NO']::text[],array['Academic']::text[],array['Original research']::text[],array[]::text[],array['Violence prevention','Safeguarding']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cesdip','CESDIP — sociological research on law and penal institutions','https://www.cesdip.fr/','cesdip.fr','CESDIP — sociological research on law and penal institutions','CESDIP is a French social science research centre specialising in crime, policing and penal institutions. Its researchers use qualitative and quantitative methods to examine public security, justice, discrimination and relationships between institutions and communities. The website provides projects, publications, seminars and links to open research.','/assets/sources/cesdip-identity.webp','FR',array['FR']::text[],array['Academic']::text[],array['Original research']::text[],array[]::text[],array['Neighbourhood policing','Leadership']::text[],array['fr']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('eucpn','European Crime Prevention Network','https://eucpn.org/','eucpn.org','European Crime Prevention Network','The European Crime Prevention Network shares knowledge and practical resources for crime prevention across Europe. Its website offers toolboxes, policy papers, mythbusters, evaluated practice examples and a searchable knowledge centre. Resources address particular crime problems and support practitioners and policymakers in designing and evaluating preventive approaches.','/assets/sources/eucpn-identity.svg','BE',array['region:Europe']::text[],array['Official']::text[],array['Evidence reviews','Implementation guides','Practice examples']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('efus','European Forum for Urban Security','https://efus.eu/','efus.eu','European Forum for Urban Security','The European Forum for Urban Security brings together local and regional authorities working on urban safety and crime prevention. Its resources include publications, practice examples, projects and training on policing, public spaces, violence, technology and community participation. Some activities and materials are associated with membership.','/assets/sources/efus-identity.webp','FR',array['region:Europe']::text[],array['Professional society']::text[],array['Practice examples','Implementation guides','Commentary']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en','fr']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('aic','Australian Institute of Criminology','https://www.aic.gov.au/research','aic.gov.au','Australian Institute of Criminology','The Australian Institute of Criminology is Australia''s national research and knowledge centre on crime and criminal justice. It publishes research reports, statistical monitoring and shorter policy resources covering subjects including violence, cybercrime, organised crime and exploitation. Its research pages also explain current priorities and provide access to earlier publications.',null,'AU',array['AU']::text[],array['Official']::text[],array['Original research','Datasets','Research summaries']::text[],array[]::text[],array['Crime prevention','Investigations']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('griffith','Griffith Criminology Institute','https://www.griffith.edu.au/research/arts-education-law/criminology-institute','griffith.edu.au','Griffith Criminology Institute','Griffith Criminology Institute brings together criminology researchers working on crime prevention, policing, justice and community safety. Its website describes research themes, partnerships and specialist facilities, and links to researchers and projects. Areas include youth justice, violence, corrections, technology and the translation of research into policy and practice.','/assets/sources/griffith-identity.webp','AU',array['AU']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('sfu-criminology','Simon Fraser University — criminology research','https://www.sfu.ca/criminology/research/research-clusters.html','sfu.ca','Simon Fraser University — criminology research','Simon Fraser University''s School of Criminology organises research across clusters covering crime prevention, policing, criminal justice and related social issues. The research directory identifies academic interests and public professional contacts, helping users find relevant expertise. Linked university pages provide further information about research centres, publications and individual researchers.','/assets/sources/sfu-criminology-identity.webp','CA',array['CA']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Neighbourhood policing','Leadership']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('public-safety-canada','Public Safety Canada — research publications','https://www.publicsafety.gc.ca/cnt/rsrcs/pblctns/index-en.aspx','publicsafety.gc.ca','Public Safety Canada — research publications','Public Safety Canada''s publications collection brings together government research, evaluations, statistics and policy reports. Searchable topics include policing, crime prevention, community safety, violence and criminal justice, alongside wider public safety responsibilities. Reports differ in purpose and method, so users should consult each publication''s date, scope and evaluation approach.','/assets/sources/public-safety-canada-identity.webp','CA',array['CA']::text[],array['Official']::text[],array['Original research','Research summaries']::text[],array[]::text[],array['Crime prevention','Leadership']::text[],array['en','fr']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cebcp','Center for Evidence-Based Crime Policy','https://cebcp.org/','cebcp.org','Center for Evidence-Based Crime Policy','Based at George Mason University, the Center for Evidence-Based Crime Policy connects research with decisions about crime and justice. Its resources include the Evidence-Based Policing Matrix, systematic reviews, research projects, briefings and practitioner publications. Work covers policing, crime and place, and broader criminal justice policy.','/assets/sources/cebcp-identity.webp','US',array['US']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('perforum','Police Executive Research Forum','https://www.policeforum.org/','policeforum.org','Police Executive Research Forum','The Police Executive Research Forum is a research and policy organisation supporting police leadership and organisational improvement. It publishes reports and practical resources, provides executive education and offers technical assistance. Its website covers topics including use of force, supervision, community relationships and emerging challenges for police organisations.','/assets/sources/perforum-identity.webp','US',array['US']::text[],array['Professional society']::text[],array['Learning resources','Practice examples']::text[],array[]::text[],array['Leadership','Police wellbeing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('police-foundation-us','National Policing Institute','https://www.policinginstitute.org/','policinginstitute.org','National Policing Institute','The National Policing Institute is an independent research and policy organisation focused on improving policing through evidence, innovation and collaboration. Its website provides evaluations, reports, practical guides and project information on crime prevention, community partnerships, police operations, technology, staffing and organisational practice. It was previously known as the Police Foundation.','/assets/sources/police-foundation-us-identity.webp','US',array['US']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Leadership','Neighbourhood policing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('rand-policing','RAND — policing research','https://www.rand.org/topics/law-enforcement.html','rand.org','RAND — policing research','RAND''s law enforcement collection brings together research reports, expert analysis and commentary on policing and public safety. Topics include police organisations, community relationships, crime prevention, technology and reform. Users can browse current and earlier work and follow links to individual publications for their methods, findings and limitations.',null,'US',array['US']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Leadership','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('crime-lab','University of Chicago Crime Lab','https://crimelab.uchicago.edu/','crimelab.uchicago.edu','University of Chicago Crime Lab','The University of Chicago Crime Lab works with public agencies and community partners to design, test and expand responses to violence and criminal justice challenges. Its website provides research projects, resources and information about data partnerships and leadership programmes, with a particular focus on reducing gun violence.','/assets/sources/crime-lab-identity.svg','US',array['US']::text[],array['University','Academic']::text[],array['Original research']::text[],array[]::text[],array['Violence prevention','Crime prevention']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('iss','Institute for Security Studies — Crime Hub','https://crimehub.org/','crimehub.org','Institute for Security Studies — Crime Hub','The Institute for Security Studies'' Crime Hub provides South African crime statistics, interactive tools, research and analysis. Its topics include evidence-based policing, professional policing, violence prevention, prosecutions and corruption. Users can explore national and local crime patterns and follow links to publications explaining data sources and policy questions.','/assets/sources/iss-identity.svg','ZA',array['ZA','region:Africa']::text[],array['Independent']::text[],array['Original research','Datasets','Commentary']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('apcof','African Policing Civilian Oversight Forum','https://apcof.org/','apcof.org','African Policing Civilian Oversight Forum','The African Policing Civilian Oversight Forum works on police accountability, governance and human rights across Africa. Its website provides research papers, policy submissions, manuals, guides and project reports. The organisation combines research, advocacy, partnerships and technical support to strengthen oversight and relationships between police and communities.','/assets/sources/apcof-identity.webp','ZA',array['region:Africa']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Leadership','Neighbourhood policing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('csvr','Centre for the Study of Violence and Reconciliation','https://csvr.org.za/','csvr.org.za','Centre for the Study of Violence and Reconciliation','The Centre for the Study of Violence and Reconciliation is an independent South African organisation researching violence and supporting affected communities. Its publications address violence prevention, criminal justice, state accountability, trauma, gender and transitional justice. The website combines research outputs with advocacy material, programme information and psychosocial support resources.','/assets/sources/csvr-identity.webp','ZA',array['ZA','region:Africa']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Violence prevention','Police wellbeing']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('chrips','Centre for Human Rights and Policy Studies','https://chrips.or.ke/','chrips.or.ke','Centre for Human Rights and Policy Studies','The Centre for Human Rights and Policy Studies is a Kenyan research organisation working on security, human rights and public policy. Its public resources include reports, policy briefs and project information on policing, accountability, violence prevention and violent extremism, with particular attention to community engagement and African contexts.',null,'KE',array['KE','region:Africa']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Neighbourhood policing','Violence prevention']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('igarape','Igarapé Institute','https://igarape.org.br/en/','igarape.org.br','Igarapé Institute','The Igarapé Institute is an independent research organisation publishing analysis and data tools on security, violence and related global challenges. Its website includes work on public safety, organised crime, violence prevention and institutional responses, alongside nature and climate programmes. Much of its security research focuses on Brazil and Latin America.','/assets/sources/igarape-identity.webp','BR',array['BR','region:South America','global']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Crime prevention','Violence prevention']::text[],array['en','pt']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('fbsp','Brazilian Forum on Public Safety — publications','https://publicacoes.forumseguranca.org.br/','publicacoes.forumseguranca.org.br','Brazilian Forum on Public Safety — publications','The Brazilian Forum on Public Safety''s digital repository organises its institutional research and publications. Collections include public security yearbooks, the Atlas of Violence, policing, prevention, justice and public spending. Users can browse thematic collections or search individual reports, with most material published in Portuguese and focused on Brazil.',null,'BR',array['BR']::text[],array['Independent']::text[],array['Original research','Datasets','Practice examples']::text[],array[]::text[],array['Violence prevention','Leadership']::text[],array['pt']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('paz-ciudadana','Fundación Paz Ciudadana','https://pazciudadana.cl/','pazciudadana.cl','Fundación Paz Ciudadana','Fundación Paz Ciudadana publishes Chilean research and policy resources on crime prevention, public safety and criminal justice. Its website includes a research library, criminal analysis materials, victimisation indicators and work on rehabilitation and reoffending. Publications and project pages provide further context on the organisation''s studies and practical partnerships.','/assets/sources/paz-ciudadana-identity.svg','CL',array['CL']::text[],array['Independent']::text[],array['Original research','Datasets','Practice examples']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('ideas-paz','Fundación Ideas para la Paz','https://ideaspaz.org/','ideaspaz.org','Fundación Ideas para la Paz','Fundación Ideas para la Paz is a Colombian research organisation examining security, conflict, governance and peacebuilding. Its website offers reports, analysis, monitoring publications and practical tools, including work on organised crime, territorial security and relationships between institutions and communities. Users should distinguish research findings from the organisation''s commentary and policy proposals.',null,'CO',array['CO']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Violence prevention','Neighbourhood policing']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('insyde','Instituto para la Seguridad y la Democracia','https://insyde.org.mx/','insyde.org.mx','Instituto para la Seguridad y la Democracia','Instituto para la Seguridad y la Democracia is a Mexican organisation working on democratic security and criminal justice. Its website provides publications, project information and training on police reform, accountability and human mobility. Resources include practical work with police organisations and citizen oversight, alongside policy analysis and professional development material.','/assets/sources/insyde-identity.webp','MX',array['MX']::text[],array['Independent']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Leadership','Neighbourhood policing']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('unodc','UNODC — crime and criminal justice research','https://www.unodc.org/unodc/en/data-and-analysis/','unodc.org','UNODC — crime and criminal justice research','The United Nations Office on Drugs and Crime publishes international research, statistics and methodological resources on crime, drugs and criminal justice. Its research pages link to data tools and studies covering homicide, trafficking, organised crime, corruption and other topics. Users should check country coverage, reference periods and definitions before comparing figures.',null,'AT',array['global']::text[],array['Official']::text[],array['Original research','Implementation guides']::text[],array[]::text[],array['Crime prevention','Investigations']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('unafei','United Nations Asia and Far East Institute','https://www.unafei.or.jp/english/publications/','unafei.or.jp','United Nations Asia and Far East Institute','The United Nations Asia and Far East Institute publishes materials from international criminal justice training and research activities in Japan. Its collection includes annual reports, newsletters, seminar papers and the Resource Material Series. Topics span crime prevention, criminal justice administration, rehabilitation and international cooperation, combining expert contributions and practitioner perspectives.',null,'JP',array['region:Asia','global']::text[],array['Official']::text[],array['Learning resources','Practitioner stories']::text[],array[]::text[],array['Crime prevention','Leadership']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
